/** Verify unchanged safe-export/import files with local fixtures only. */
const fs=require("node:fs"),assert=require("node:assert/strict");
const path=require("node:path");
const {chromium}=require(process.env.USP_PLAYWRIGHT_MODULE||path.resolve(__dirname,"../tools/web-ui/node_modules/playwright"));
const args=process.argv.slice(2),option=n=>{const index=args.indexOf(n);return index<0?undefined:args[index+1]};

/** Isolate source events and capture the actual Blob generated by Export. */
async function install(page,script,group,language) {
  await page.addInitScript(()=>{
    localStorage.setItem("usp-active-tab","maintenance");
    const original=URL.createObjectURL.bind(URL);
    URL.createObjectURL=blob=>{window.backupBlob=blob;return original(blob)};
    window.EventSource=class extends EventTarget {
      constructor(){super();window.fixtureSource=this}
      emit(value){this.dispatchEvent(new MessageEvent("state",{data:JSON.stringify(value)}))}
    };
  });
  await page.route("**/*",r=>{
    const u=new URL(r.request().url());
    if(u.pathname==="/")return r.fulfill({contentType:"text/html",body:"<!doctype html><esp-app></esp-app><script type=module src=/app.js></script>"});
    if(u.pathname==="/app.js")return r.fulfill({contentType:"text/javascript",body:script});
    throw Error("Unexpected request; no writes permitted: "+u.href);
  });
  await page.goto("http://backup-fixture.test/");
  await page.evaluate(({group,language})=>{
    fixtureSource.emit({id:"lang",name:"UI Language",domain:"select",sorting_group:"Panel settings",value:language,option:[language]});
    fixtureSource.emit({id:"group",name:"Outage Group Code",domain:"text",sorting_group:"SvitloBot",state:group,min_length:1,max_length:8});
  },{group,language});
}

/** Use the real export action and feed its unmodified bytes into the file input. */
async function scenario(browser,script,group,language) {
  const page=await browser.newPage();
  await install(page,script,group,language);
  const section=page.locator(".usp-group").first();
  await section.locator("button").first().click();
  const content=await page.evaluate(()=>backupBlob.text());
  const exported=JSON.parse(content);
  await page.locator('input[type="file"]').setInputFiles({
    name:"fixture-backup.json",mimeType:"application/json",buffer:Buffer.from(content)});
  await page.waitForTimeout(150);
  const importAccepted=await section.locator("button").nth(2).isEnabled();
  const plan=await page.evaluate(content=>{
    const doc=JSON.parse(content),before=JSON.stringify(doc);
    const plan=document.querySelector("esp-app").restorePlan(doc);
    return {plan,input_unchanged:before===JSON.stringify(doc)};
  },content);
  assert.equal(plan.input_unchanged,true,"import validation must not mutate the backup");
  if(group==="--"||group===null)
    assert.equal(plan.plan.some(row=>row[0]==="Outage Group Code"),false,"unknown group must not overwrite current group");
  if(group==="10.1") assert.ok(plan.plan.some(row=>row[0]==="Outage Group Code"&&row[2]==="10.1"));
  const result={input_group:group,language,expected:["--",null,"10.1"].includes(group),exported_group:exported.settings.outageGroup,
    import_accepted:importAccepted,unchanged_export:true};
  await page.close();
  return result;
}

/** Save the failing baseline before reporting a failed roundtrip. */
async function main() {
  if(args.includes("--help")){console.log("node tests/web-backup-roundtrip-browser.cjs --script FILE [--output NEW.json]");return}
  assert.ok(option("--script"),"--script is required");
  const script=fs.readFileSync(option("--script"),"utf8"),rows=[];
  const browser=await chromium.launch({headless:true});
  try {
    for(const language of ["English","Русский","Українська"]) for(const group of ["--",null,"10.1","bad","61.1","10.0","10.12","<x>"]) rows.push(await scenario(browser,script,group,language));
  } finally {await browser.close()}
  const report={status:rows.every(r=>r.import_accepted===r.expected)?"PASS":"FAIL",
    rows,device_contact:false,settings_applied:false,fixture_only:true};
  if(option("--output"))fs.writeFileSync(option("--output"),JSON.stringify(report,null,2)+"\n",{flag:"wx"});
  assert.equal(report.status,"PASS","F-W6 unchanged exported configuration cannot be imported");
  console.log("FW6_BACKUP_ROUNDTRIP=PASS");
}
main().catch(e=>{console.error(e);process.exitCode=1;});
